import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Deque;
import java.util.List;

final class ConnectedComponents {

    private ConnectedComponents() {
    }

    static List<List<Integer>> findComponents(UndirectedGraph graph) {
        int vertexCount = graph.size();
        boolean[] visited = new boolean[vertexCount];
        List<List<Integer>> components = new ArrayList<>(vertexCount);

        for (int vertex = 0; vertex < vertexCount; vertex++) {
            if (!visited[vertex]) {
                List<Integer> component = new ArrayList<>();
                bfs(graph, vertex, visited, component);
                components.add(Collections.unmodifiableList(component));
            }
        }
        return Collections.unmodifiableList(components);
    }

    private static void bfs(UndirectedGraph graph, int source, boolean[] visited, List<Integer> component) {
        Deque<Integer> queue = new ArrayDeque<>();
        visited[source] = true;
        queue.addLast(source);

        while (!queue.isEmpty()) {
            int currentVertex = queue.removeFirst();
            component.add(currentVertex);

            for (int neighbor : graph.neighborsOf(currentVertex)) {
                if (!visited[neighbor]) {
                    visited[neighbor] = true;
                    queue.addLast(neighbor);
                }
            }
        }
    }
}

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

final class UndirectedGraph {
    private final List<List<Integer>> adjacency;

    UndirectedGraph(int vertexCount) {
        if (vertexCount < 0) {
            throw new IllegalArgumentException("vertexCount must be non-negative");
        }
        adjacency = new ArrayList<>(vertexCount);
        for (int vertex = 0; vertex < vertexCount; vertex++) {
            adjacency.add(new ArrayList<>());
        }
    }

    int size() {
        return adjacency.size();
    }

    void addUndirectedEdge(int u, int v) {
        validateVertex(u);
        validateVertex(v);
        adjacency.get(u).add(v);
        adjacency.get(v).add(u);
    }

    List<Integer> neighborsOf(int vertex) {
        validateVertex(vertex);
        return Collections.unmodifiableList(adjacency.get(vertex));
    }

    private void validateVertex(int vertex) {
        if (vertex < 0 || vertex >= adjacency.size()) {
            throw new IllegalArgumentException("Vertex out of range: " + vertex);
        }
    }
}

import java.util.List;

final class ConnectedComponentsDemo {

    private ConnectedComponentsDemo() {
    }

    public static void main(String[] args) {
        List<List<Integer>> components = ConnectedComponents.findComponents(sampleGraph());
        printComponents(components);
    }

    private static UndirectedGraph sampleGraph() {
        UndirectedGraph graph = new UndirectedGraph(6);
        graph.addUndirectedEdge(1, 2);
        graph.addUndirectedEdge(0, 3);
        graph.addUndirectedEdge(2, 0);
        graph.addUndirectedEdge(5, 4);
        return graph;
    }

    private static void printComponents(List<List<Integer>> components) {
        for (List<Integer> component : components) {
            System.out.println(joinIntegers(component));
        }
    }

    private static String joinIntegers(List<Integer> values) {
        StringBuilder line = new StringBuilder();
        for (int index = 0; index < values.size(); index++) {
            if (index > 0) {
                line.append(' ');
            }
            line.append(values.get(index));
        }
        return line.toString();
    }
}

